package dev.hybridmail;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.*;import com.google.gson.*;
public class PrfVaultTest {
 @Test public void roundTripMultiPasskeyAndNoPlaintext()throws Exception{Path p=Files.createTempDirectory("vault-test").resolve("vault.json");byte[] a=PrfVault.random(32),b=PrfVault.random(32);try{var v=new PrfVault(p);v.create("YWJj",PrfVault.random(32),a);v.put("microsoft.refresh","synthetic-refresh-secret");v.put("imap.password","synthetic-imap-secret");v.addPasskey("ZGVm",PrfVault.random(32),b);v.close();String disk=new String(Files.readAllBytes(p),java.nio.charset.StandardCharsets.UTF_8);assertFalse(disk.contains("synthetic"));assertFalse(disk.contains("microsoft.refresh"));assertFalse(disk.contains(PrfVault.b64(a)));assertFalse(disk.contains(PrfVault.b64(b)));var restored=new PrfVault(p);assertFalse(restored.unlocked());restored.unlock("YWJj",a);assertEquals("synthetic-refresh-secret",restored.get("microsoft.refresh"));restored.close();restored.unlock("ZGVm",b);assertEquals("synthetic-imap-secret",restored.get("imap.password"));restored.close();try{restored.get("imap.password");fail();}catch(IllegalStateException expected){}}finally{Files.deleteIfExists(p);Files.deleteIfExists(p.getParent());}}
 @Test public void wrongPrfAndTamperingFailClosed()throws Exception{Path p=Files.createTempDirectory("vault-test").resolve("vault.json");byte[] a=PrfVault.random(32);try{var v=new PrfVault(p);v.create("YWJj",PrfVault.random(32),a);v.put("password","synthetic");v.close();try{v.unlock("YWJj",PrfVault.random(32));fail();}catch(java.security.GeneralSecurityException expected){}assertFalse(v.unlocked());var j=JsonParser.parseString(new String(Files.readAllBytes(p),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();var payload=j.getAsJsonObject("payload");byte[] cipher=PrfVault.decode(payload.get("ciphertext").getAsString());cipher[0]^=1;payload.addProperty("ciphertext",PrfVault.b64(cipher));Files.write(p,j.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));var broken=new PrfVault(p);try{broken.unlock("YWJj",a);fail();}catch(java.security.GeneralSecurityException expected){}assertFalse(broken.unlocked());}finally{Files.deleteIfExists(p);Files.deleteIfExists(p.getParent());}}
 @Test public void missingPrfAndWrongContextRejected()throws Exception{String origin="android:apk-key-hash:synthetic",challenge="challenge";var j=new JsonObject();j.addProperty("rawId","YWJj");j.addProperty("type","public-key");var r=new JsonObject();var client=new JsonObject();client.addProperty("challenge",challenge);client.addProperty("origin",origin);client.addProperty("type","webauthn.get");r.addProperty("clientDataJSON",PrfVault.b64(client.toString().getBytes()));byte[] auth=new byte[37];System.arraycopy(java.security.MessageDigest.getInstance("SHA-256").digest(PrfVault.RP.getBytes()),0,auth,0,32);auth[32]=5;r.addProperty("authenticatorData",PrfVault.b64(auth));j.add("response",r);try{AndroidPasskeyPrf.result(j,"YWJj",challenge,origin);fail();}catch(SecurityException expected){}var ext=new JsonObject();var prf=new JsonObject();var results=new JsonObject();byte[] output=PrfVault.random(32);results.addProperty("first",PrfVault.b64(output));prf.add("results",results);ext.add("prf",prf);j.add("clientExtensionResults",ext);assertArrayEquals(output,AndroidPasskeyPrf.result(j,"YWJj",challenge,origin));auth[32]=1;r.addProperty("authenticatorData",PrfVault.b64(auth));try{AndroidPasskeyPrf.result(j,"YWJj",challenge,origin);fail();}catch(SecurityException expected){}try{AndroidPasskeyPrf.client(j,"wrong",origin,"webauthn.get");fail();}catch(SecurityException expected){}}
 @Test public void namesAndRemovalPersistWithoutLockout()throws Exception{Path p=Files.createTempDirectory("vault-test").resolve("vault.json");byte[] a=PrfVault.random(32),b=PrfVault.random(32);try{var v=new PrfVault(p);v.create("YWJj",PrfVault.random(32),a);v.renamePasskey("YWJj","Pixel passkey");assertEquals("Pixel passkey",v.passkeyName("YWJj"));v.close();assertEquals("Pixel passkey",new PrfVault(p).passkeyName("YWJj"));v.unlock("YWJj",a);try{v.removePasskey("YWJj");fail();}catch(SecurityException expected){}v.addPasskey("ZGVm",PrfVault.random(32),b);v.renamePasskey("ZGVm","Backup key");v.removePasskey("YWJj");v.close();var restored=new PrfVault(p);assertEquals("Backup key",restored.passkeyName("ZGVm"));try{restored.unlock("YWJj",a);fail();}catch(SecurityException expected){}restored.unlock("ZGVm",b);assertEquals("Backup key",restored.passkeyName("ZGVm"));assertEquals(1,restored.wrappers().size());restored.close();}finally{Files.deleteIfExists(p);Files.deleteIfExists(p.getParent());}}
 @Test public void creationPrfAndFallback()throws Exception{String origin="android:apk-key-hash:synthetic",challenge="new-challenge";var response=new JsonObject();response.addProperty("rawId","YWJj");response.addProperty("type","public-key");var body=new JsonObject();var client=new JsonObject();client.addProperty("origin",origin);client.addProperty("challenge",challenge);client.addProperty("type","webauthn.create");body.addProperty("clientDataJSON",PrfVault.b64(client.toString().getBytes()));byte[] auth=new byte[59];System.arraycopy(java.security.MessageDigest.getInstance("SHA-256").digest(PrfVault.RP.getBytes()),0,auth,0,32);auth[32]=0x45;auth[54]=3;System.arraycopy("abc".getBytes(),0,auth,55,3);auth[58]=(byte)0xa0;var cbor=new java.io.ByteArrayOutputStream();cbor.write(0xa1);cbor.write(0x68);cbor.write("authData".getBytes());cbor.write(0x58);cbor.write(auth.length);cbor.write(auth);body.addProperty("attestationObject",PrfVault.b64(cbor.toByteArray()));response.add("response",body);assertNull(AndroidPasskeyPrf.creationResult(response,challenge,origin));var ext=new JsonObject();var prf=new JsonObject();prf.addProperty("enabled",true);var results=new JsonObject();byte[] output=PrfVault.random(32);results.addProperty("first",PrfVault.b64(output));prf.add("results",results);ext.add("prf",prf);response.add("clientExtensionResults",ext);assertArrayEquals(output,AndroidPasskeyPrf.creationResult(response,challenge,origin));prf.addProperty("enabled",false);try{AndroidPasskeyPrf.creationResult(response,challenge,origin);fail();}catch(SecurityException expected){}try{AndroidPasskeyPrf.creationResult(response,"wrong",origin);fail();}catch(SecurityException expected){}}
 @Test public void olderEncryptedNamesUpgradeOnUnlock()throws Exception{Path p=Files.createTempDirectory("vault-test").resolve("vault.json");byte[] a=PrfVault.random(32);try{var v=new PrfVault(p);v.create("YWJj",PrfVault.random(32),a);v.put("passkey.name.YWJj","My device");v.close();var restored=new PrfVault(p);assertNotEquals("My device",restored.passkeyName("YWJj"));restored.unlock("YWJj",a);restored.close();assertEquals("My device",new PrfVault(p).passkeyName("YWJj"));}finally{Files.deleteIfExists(p);Files.deleteIfExists(p.getParent());}}
}
